#!/bin/bash
# s2_deploy2.sh: медиа-страницы S2 (cinema/music/news/studio) + сбор каталогов. Бэкапы *.bak_s2_1
S=/workspace/nox/web/site; set -u
df -h /workspace | tail -1
for f in cinema.html music.html news.html studio.html; do [ -f $S/$f.bak_s2_1 ] || cp $S/$f $S/$f.bak_s2_1; done
mkdir -p $S/data /workspace/nox/state/cinema_catalog /workspace/nox/tools
base64 -d > $S/nox-s2.css <<'B64EOF'

B64EOF
base64 -d > $S/nox-s2-cinema.js <<'B64EOF'

B64EOF
base64 -d > $S/nox-s2-music.js <<'B64EOF'

B64EOF
base64 -d > $S/nox-s2-news.js <<'B64EOF'

B64EOF
base64 -d > $S/nox-s2-studio.js <<'B64EOF'

B64EOF
base64 -d > $S/cinema.html <<'B64EOF'

B64EOF
base64 -d > $S/music.html <<'B64EOF'

B64EOF
base64 -d > $S/news.html <<'B64EOF'

B64EOF
base64 -d > $S/studio.html <<'B64EOF'

B64EOF
base64 -d > /workspace/nox/tools/s2_feeds.py <<'B64EOF'

B64EOF
python3 - <<'PY'
import re
S='/workspace/nox/web/site/'
old=open(S+'music.html.bak_s2_1',encoding='utf-8').read()
m=re.search(r'(<section class="card"><h2>Служба.*?)</div></main>',old,re.S)
new=open(S+'music.html',encoding='utf-8').read()
blk='<div id="muOld" hidden>'+(m.group(1) if m else '')+'</div>'
new=new.replace('<!--S2_KEEP_OLD-->',blk).replace('<script type="module" src="./nox-nav.js"></script>','<script type="module" src="./nox-nav.js"></script>\n<script type="module" src="./nox-p-media.js"></script>',1)
open(S+'music.html','w',encoding='utf-8').write(new)
print('music old block',bool(m),len(blk))
PY
cd /workspace/nox/tools
timeout 120 python3 s2_feeds.py news 2>&1 | tail -3
timeout 400 python3 s2_feeds.py catalog 2>&1 | tail -5
pgrep -f "s2_feeds.py" >/dev/null || { nohup setsid python3 /workspace/nox/tools/s2_feeds.py loop >> /workspace/nox/svc/logs/s2_feeds.log 2>&1 < /dev/null & }
sleep 1; pgrep -fa s2_feeds | head -2
for p in cinema music news studio; do printf "$p "; curl -s -o /dev/null -w "%{http_code} %{size_download}\n" http://127.0.0.1:8091/$p.html; done
ls -la $S/data | head; df -h /workspace | tail -1
